<section class="section contact" id="contact">
  <div class="container">
    <div class="section-head center">
      <span class="eyebrow reveal">Get In Touch</span>
      <h2 data-split>Questions before you book? Talk to a local.</h2>
      <p class="lead reveal">Call, email or send us a message. We reply fast, 7 days a week.</p>
    </div>
    <div class="contact__grid">
      <div class="contact__info reveal reveal--left">
        <ul class="contact__list">
          <li><a href="tel:+61447943160"><span class="icon-circle"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.1 4.2 2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7c.1.9.4 1.8.7 2.7a2 2 0 0 1-.5 2.1L8 9.8a16 16 0 0 0 6 6l1.3-1.3a2 2 0 0 1 2.1-.4c.9.3 1.8.6 2.7.7a2 2 0 0 1 1.7 2z"/></svg></span><span><small>Call or text</small><strong>0447 943 160</strong></span></a></li>
          <li><a href="mailto:bodhi@lockii.app"><span class="icon-circle"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="2" y="4" width="20" height="16" rx="2"/><path d="m22 6-10 7L2 6"/></svg></span><span><small>Email</small><strong>bodhi@lockii.app</strong></span></a></li>
          <li><div><span class="icon-circle"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0z"/><circle cx="12" cy="10" r="3"/></svg></span><span><small>Pickup locations</small><strong>Upper Kedron &amp; Gaythorne, QLD</strong></span></div></li>
          <li><div><span class="icon-circle"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg></span><span><small>Access hours</small><strong>24/7 contactless pickup</strong></span></div></li>
        </ul>
        <div class="map">
          <iframe title="Map of NSA Trailers pickup locations in Upper Kedron and Gaythorne" loading="lazy" referrerpolicy="no-referrer-when-downgrade" src="https://maps.google.com/maps?q=Gaythorne%20QLD%204051&amp;z=12&amp;output=embed"></iframe>
        </div>
      </div>
      <div class="reveal reveal--right">
        <form class="form-card" data-demo action="#" method="post">
          <div class="form-body">
            <h3>Send us a message</h3>
            <p>Tell us what you are moving and we will recommend the right trailer.</p>
            <div class="form-grid">
              <div class="field"><label for="c-name">Full name</label><input id="c-name" name="name" required autocomplete="name" placeholder="Jane Smith"></div>
              <div class="field"><label for="c-phone">Phone</label><input id="c-phone" name="phone" type="tel" required autocomplete="tel" placeholder="04xx xxx xxx"></div>
              <div class="field field--full"><label for="c-email">Email</label><input id="c-email" name="email" type="email" required autocomplete="email" placeholder="you@email.com"></div>
              <div class="field field--full"><label for="c-topic">I need help with</label>
                <select id="c-topic" name="topic"><option>Choosing a trailer</option><option>An existing booking</option><option>Long term or multi day hire</option><option>Something else</option></select></div>
              <div class="field field--full"><label for="c-msg">Message</label><textarea id="c-msg" name="message" placeholder="I am moving a 2 bedroom unit this Saturday..."></textarea></div>
            </div>
            <button class="btn btn--dark btn--block" type="submit" style="margin-top:18px">Send Message <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14M13 5l7 7-7 7"/></svg></button>
            <p class="form-note"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/><path d="m9 12 2 2 4-4"/></svg> Your details stay private. No spam, ever.</p>
          </div>
          <div class="form-success"><span class="check"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 6 9 17l-5-5"/></svg></span><h3>Message sent</h3><p>Thanks! A member of the NSA team will be in touch shortly.</p></div>
        </form>
      </div>
    </div>
  </div>
</section>
